import { NOTICE_TONES } from '../components/notice-props'

const HEADER = `/*
 * Stencil notice CSS for StNotice: one rule per tone and variant, each reading a semantic color.
 * GENERATED by \`pnpm stencil:tokens\` from stencil/components/notice-props.ts. Do not edit by hand.
 */
`

/** Renders the StNotice rules as one stylesheet. */
export function renderNoticeCss(): string {
  const rules: string[] = [
    '.st-notice { display: flex; align-items: flex-start; gap: var(--st-space-100); box-sizing: border-box; min-width: 0; color: var(--st-notice-color); font: var(--st-type-body-compact); }',
    ...NOTICE_TONES.map(
      (tone) => `.st-notice[data-st-tone='${tone}'] { --st-notice-color: var(--st-color-${tone}); }`
    ),
    // Boxed text stays neutral: a tone color on its own 12% tint falls under AA in the light theme.
    `.st-notice[data-st-variant='boxed'] { color: var(--st-color-text-primary); padding: var(--st-space-100) var(--st-space-150); border: var(--st-border-100) solid color-mix(in srgb, var(--st-notice-color) 40%, transparent); border-radius: var(--st-space-100); background: color-mix(in srgb, var(--st-notice-color) 12%, transparent); }`,
    `.st-notice[data-st-variant='inline'] { padding: 0; }`,
    '.st-notice-body { display: flex; flex: 1; flex-direction: column; gap: var(--st-space-50); min-width: 0; }',
    '.st-notice-title { font: var(--st-type-label-md); }',
    '.st-notice-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--st-space-100); margin-top: var(--st-space-50); }'
  ]
  return `${HEADER}\n${rules.join('\n')}\n`
}
